mapper.select:
SELECT sp.store_product_id, p.product_id, p.product_sn, p.product_name, sps.product_sku_id AS productSkuId, p.product_unit, p.pic_thumb AS productPicThumb, ps.sku_value AS productSkuName, CASE WHEN sps.sku_stock IS NOT NULL THEN sps.sku_stock ELSE sp.product_stock END AS currentProductStock FROM store_product sp LEFT JOIN product p ON p.product_id = sp.product_id LEFT JOIN store_product_sku sps ON sps.store_product_id = sp.store_product_id LEFT JOIN product_sku ps ON ps.sku_id = sps.product_sku_id WHERE p.product_id is not null and sp.shop_id = #{productStockDTO.shopId}
AND (p.product_name LIKE CONCAT('%',#{productStockDTO.keyword},'%') or ps.sku_value LIKE CONCAT('%',#{productStockDTO.keyword},'%'))
order by sp.add_time
